"""Generate contract semantics and measured gas notes from the result summary."""

import json
from pathlib import Path


def main():
    data = json.loads(Path("results/summary.json").read_text(encoding="utf-8"))
    contract, gas = data["contracts"], data["gas"]
    checks = contract["checks"]
    grid = data.get("grid_settlement")
    if grid is not None:
        from document_grid_settlement import checked_coverage, main as grid_assets
        checked_coverage(grid)
        grid_assets()
    grid_status = (f"The selected-method grid matches {grid['round_rule_cases']} round-rule states across "
                   f"{grid['jobs']} declared jobs from {grid['grid_runs']} training runs. "
                   "See [grid settlement and retained balances](GRID_SETTLEMENT.md) for exact coverage by rule, "
                   "reward and stake burns, claimed amounts and outstanding vesting liabilities."
                   if grid is not None else
                   "Empirical selected-method grid replay is pending until the complete grid and declared replays exist. "
                   "Existing baseline and randomized evidence does not substitute for that coverage.")
    lines = ["# Reward contract and settlement evidence", "",
        "Generated by `python scripts/document_contracts.py` from `results/summary.json`.", "",
        "## Trust and state transitions", "",
        "The coordinator selects participants and posts off-chain scores. Commit/reveal binds a participant to a digest before scores are posted; it does not prove that local training occurred or that a score is correct. Historical replay commits the canonical participation record, including its common update-set hash, with deterministic test salts. It does not validate raw updates or provide private commitments.", "",
        "The pool deploys its own immutable ERC-20 token. Setup grants an equal endowment once per address, then registration transfers that endowment into stake. Enrollment closes when training starts. There is no participant exit or stake-withdrawal mechanism in this research implementation.", "",
        "Rounds are sequential. Only sampled, registered clients may commit or reveal. The commitment includes digest, salt, round and sender. The coordinator posts the same ordered sample after the reveal deadline; a positive reward requires a successful reveal. The score sum cannot exceed the fixed-point unit.", "",
        "Settlement first matures old rewards for every registered client, including absent clients. A flagged sampled client then loses the floored slash fraction of stake and of each still-unvested tranche. Matured and previously claimed rewards are protected. Current-round rewards are added after that slash. Token mint/burn operations occur after state changes. Claims clear the liability before transferring tokens.", "",
        "Floating shares are converted with exact Python Fraction(float) values, normalized by their exact sum, then floored into integer shares. No client receives a rounding top-up. The pool floors each reward and records the unminted remainder. Delay-zero ablations make current rewards immediately claimable; positive delays use a bounded ring of unlock rounds.", "",
        "Vesting advances with settled rounds, not wall-clock time. Rewards near the final measured round remain unvested until later rounds settle. This implementation has no separate finalization or emergency withdrawal path. Coordinator-controlled initial grants are an admission assumption, not proof of unique real-world identities.", "",
        "## Measured checks", "",
        f"- Solidity tests: {checks['tests_passed']} passed, {checks['tests_failed']} failed; {checks['fuzz_runs']:,} fuzz runs with seed `{checks['fuzz_seed']}`.",
        f"- Static findings: {checks['static_counts']['High']} high, {checks['static_counts']['Medium']} medium, {checks['static_counts']['Low']} low, {checks['static_counts']['Informational']} informational.",
        f"- Recorded FL settlement: {contract['replay_rounds']} round-rule cases with exact stake, wallet, claimable, unvested tranche, supply, pool balance and remainder checks.",
        f"- Random state histories: {contract['stress_rounds']} rounds, {contract['stress_slashes']} slash participations, vesting delays {', '.join(map(str,contract['stress_delays']))}. These include zero allocations, changing participation and deferred claims.", "",
        "The Solidity sequence fuzz test checks every settlement against a full issuance-history oracle, independent of the pool's ring slots. It covers payout conservation, collateral, exact stake and tranche burns, claims and monotonic cumulative maturity across valid vesting delays. Separate commitment fuzzing rejects both a copied prior-round commitment and a commitment bound to another sender.", "",
        f"Compiler: `{checks['compiler_version'].splitlines()[-1]}`. Foundry: `{checks['forge_version'].splitlines()[0]}`. Static analyzer: `{checks['static_version']}`. Optimizer runs: {gas['optimizer_runs']}; EVM target: {gas['evm']}.", "",
        "Low-severity timestamp findings are intentional deadline checks; block timestamp variation remains a limitation. Compiler-range and unused-context findings come from retaining the original token library. Settlement complexity is exercised through independent integer-state replay. Full classifications are in `results/contracts/checks.json`.", "",
        "## Gas scaling and transaction capacity", "",
        "The scaling experiment samples every registered client. Each case includes setup, commit/reveal, score posting, settlement and claims over the same state history. The slash round overlaps reward maturity and exercises a more expensive settlement phase. This differs from the FL reproduction, which samples a subset of registered clients.", "",
        f"[EIP-7825]({gas['cap_source']}) limits the sender-specified gas limit of an individual transaction to {gas['cap']:,}. It does not cap the sum of separate transactions in an FL round. Receipt gas may include refunds and therefore cannot establish that a transaction can execute under this limit. The scaling chain permits larger transactions to measure the curve; separate boundary runs enforce the cap.", "",
        f"Under the recorded compiler, state history and full participation, {gas['executed_success_n']} clients complete every tested round with the explicit capped transaction limit. {gas['executed_failure_n']} clients exhaust that limit in settlement at round {gas['boundary_failure_round']}. This is an executed scenario boundary, not a universal safe capacity for arbitrary histories, future compiler versions or other contracts. RPC gas estimation and wallet safety buffers may impose a more conservative limit.", "",
        "| Clients | Round | Total receipt gas | Settlement estimated gas limit |", "|---:|---:|---:|---:|"]
    for row in gas["rounds"]:
        lines.append(f"| {row['clients']} | {row['round']} | {row['total_gas']:,} | {row['settle_estimated_limit']:,} |")
    lines += ["", "Linear least-squares fits use all measured client counts. Residuals expose departures from an exact linear model.", "",
              "| Operation and phase | Intercept | Gas/client | R squared | Maximum absolute residual |",
              "|---|---:|---:|---:|---:|"]
    for name, fit in gas["fits"].items():
        lines.append(f"| {name} | {fit['intercept']:.2f} | {fit['slope']:.2f} | {fit['r_squared']:.8f} | {fit['max_absolute_residual']:.2f} |")
    lines += ["", "## Published gas comparison", "",
        "The source Table 1 uses a different reward contract and operation boundaries. Values below are descriptive comparisons, not speedups for equivalent functionality. Our deployment includes a token deployment; setup endowment, token approval and commit/reveal are separate operations. Slash, maturity and reward creation share one settlement transaction.", "",
        "| Published operation | Published receipt gas |", "|---|---:|"]
    for name,value in data["published"]["standard_gas"].items():
        lines.append(f"| {name} | {value:,} |")
    lines += ["", "Our operation ranges across the measured histories (per transaction):", "",
              "| Clients | Operation | Minimum | Maximum | Mean |", "|---:|---|---:|---:|---:|"]
    for row in gas["operations"]:
        lines.append(f"| {row['clients']} | {row['operation']} | {row['minimum']:,} | {row['maximum']:,} | {row['mean']:.2f} |")
    if "portability" in contract:
        proof = contract["portability"]
        lines += ["", "## Cross-platform reconstruction", "",
            f"Actual Linux Python {proof['python']} execution passes {len(proof['checks'])} comparison checks against the Windows measurements. All {proof['replay_round_rule_cases']} round-rule states, every transaction gas value, random state histories, scaling fits and capped boundary results agree exactly. Only replay wall-clock times are excluded from equality; both measured times remain recorded.", "",
            "To reproduce the comparison without replacing the recorded Windows inputs, use the Linux chain environment:", "", "```bash",
            "python scripts/check_contracts.py --output out/linux-contract-checks.json",
            "python scripts/replay_onchain.py results/runs/mnist-sendros_mix-s42-cpu-t20 results/runs/mnist-sendros_mix-s43-cpu-t20 results/runs/mnist-sendros_mix-s44-cpu-t20 --output out/linux-onchain",
            "python scripts/check_chain_states.py --output out/linux-chain-stress.json",
            "python scripts/measure_gas.py --output out/linux-gas",
            f"python scripts/measure_gas.py --sizes {gas['executed_success_n']} {gas['executed_failure_n']} --capped --output out/linux-gas/boundary",
            "python scripts/check_contract_portability.py --checks out/linux-contract-checks.json --replays out/linux-onchain --stress out/linux-chain-stress.json --gas out/linux-gas --output out/contract-portability.json",
            "```", ""]
    lines += ["", "## Full-grid replay coverage", "",
        "The resumable `scripts/replay_grid.py` driver runs in the training environment and launches the isolated chain interpreter supplied with `--chain-python`. It requires every B1 and Mstar ledger, including long runs. The B0/B2 sample uses the first declared seed across all single attacks at the largest fraction, the attack-free condition and both mixture horizons.", "",
        "Use `--available` while training continues; the coverage file records partial completion explicitly. The default requires a complete grid. `--no-run` verifies saved evidence without launching chains. Every cached case must match its input hashes, complete source provenance, rule, vesting delay and independently reconstructed state history. The aggregate driver records the exact input manifest digest read at startup, so a concurrent training run cannot silently replace that provenance.", "",
        grid_status, ""]
    lines += ["", "## Reproduction", "", "Install the pinned offline tools and isolated Python chain environment using the README. Then run:", "", "```bash",
        "python scripts/check_contracts.py",
        "python scripts/replay_onchain.py results/runs/mnist-sendros_mix-s42-cpu-t20 results/runs/mnist-sendros_mix-s43-cpu-t20 results/runs/mnist-sendros_mix-s44-cpu-t20",
        "python scripts/check_chain_states.py",
        "python scripts/measure_gas.py",
        f"python scripts/measure_gas.py --sizes {gas['executed_success_n']} {gas['executed_failure_n']} --capped --output results/gas/boundary",
        "```", "", "In the training/artifact environment, validate recorded state histories and regenerate presentation assets:", "", "```bash",
        "python scripts/summarize_contracts.py", "python scripts/document_contracts.py", "python scripts/make_macros.py", "python scripts/make_figures.py", "```", "",
        "The chain commands create local ephemeral chains only. Local unlocked accounts and deterministic salts are test infrastructure, not a public-network key-management design. A public demo remains separate from these measurements.", ""]
    Path("docs/CONTRACTS.md").write_text("\n".join(lines),encoding="utf-8",newline="\n")
    path = Path("README.md")
    readme = path.read_text(encoding="utf-8")
    start, end = "<!-- generated contract start -->", "<!-- generated contract end -->"
    before, rest = readme.split(start, 1)
    _, after = rest.split(end, 1)
    block = (f"\nSolidity: {checks['tests_passed']} tests and {checks['fuzz_runs']:,} fuzz cases pass; "
             f"static analysis reports {checks['static_counts']['High']} high and {checks['static_counts']['Medium']} medium findings.\n"
             f"Recorded chain replay matches {contract['replay_rounds']} round-rule cases exactly; "
             f"state stress checks cover {contract['stress_rounds']} rounds and {contract['stress_slashes']} slash participations.\n"
             f"The executed full-participation gas boundary is {gas['executed_success_n']} successful clients and "
             f"{gas['executed_failure_n']} clients exhausting the settlement transaction limit under the recorded state history.\n")
    block += (f"Selected-method grid settlement matches {grid['round_rule_cases']} round-rule states in {grid['jobs']} jobs; "
              "[coverage and economic balances](docs/GRID_SETTLEMENT.md) retain the complete and sampled rules separately.\n"
              if grid is not None else "Selected-method grid settlement remains pending.\n")
    path.write_text(before+start+block+end+after,encoding="utf-8",newline="\n")
    print("Generated contract semantics and gas notes")


if __name__ == "__main__":
    main()
